export interface SidecarEnvValues {
  readonly allow_non_loopback: boolean;
  readonly bind: string;
  readonly fiducia_az?: string;
  readonly fiducia_brain_url?: string;
  readonly fiducia_export_target?: string;
  readonly fiducia_internal_secret?: string;
  readonly fiducia_log_sink?: string;
  readonly fiducia_log_source?: string;
  readonly fiducia_node_address?: string;
  readonly fiducia_node_id?: string;
  readonly fiducia_node_log_source?: string;
  readonly fiducia_node_url?: string;
  readonly fiducia_node_version?: string;
  readonly fiducia_rack?: string;
  readonly fiducia_region?: string;
  readonly fiducia_sidecar_role?: string;
  readonly port?: string;
}

/** Pure: resolve values from an explicit lookup. */
export function loadFrom(lookup: (key: string) => string | undefined): SidecarEnvValues {
  return {
    allow_non_loopback: parseBool(lookup("ORES_OTEL_SIDECAR_ALLOW_NON_LOOPBACK"), false),
    bind: nonEmpty(lookup("FIDUCIA_SIDECAR_BIND")) ?? "127.0.0.1:9090",
    fiducia_az: nonEmpty(lookup("FIDUCIA_AZ")),
    fiducia_brain_url: nonEmpty(lookup("FIDUCIA_BRAIN_URL")),
    fiducia_export_target: nonEmpty(lookup("FIDUCIA_EXPORT_TARGET")),
    fiducia_internal_secret: nonEmpty(lookup("FIDUCIA_INTERNAL_SECRET")),
    fiducia_log_sink: nonEmpty(lookup("FIDUCIA_LOG_SINK")),
    fiducia_log_source: nonEmpty(lookup("FIDUCIA_LOG_SOURCE")),
    fiducia_node_address: nonEmpty(lookup("FIDUCIA_NODE_ADDRESS")),
    fiducia_node_id: nonEmpty(lookup("FIDUCIA_NODE_ID")),
    fiducia_node_log_source: nonEmpty(lookup("FIDUCIA_NODE_LOG_SOURCE")),
    fiducia_node_url: nonEmpty(lookup("FIDUCIA_NODE_URL")),
    fiducia_node_version: nonEmpty(lookup("FIDUCIA_NODE_VERSION")),
    fiducia_rack: nonEmpty(lookup("FIDUCIA_RACK")),
    fiducia_region: nonEmpty(lookup("FIDUCIA_REGION")),
    fiducia_sidecar_role: nonEmpty(lookup("FIDUCIA_SIDECAR_ROLE")),
    port: nonEmpty(lookup("PORT")),
  };
}

/** Effectful: read the process environment. */
export function loadFromOs(
  env: Record<string, string | undefined> = typeof process !== "undefined" ? process.env : {},
): SidecarEnvValues {
  return loadFrom((key) => env[key]);
}

function nonEmpty(raw: string | undefined): string | undefined {
  const value = raw?.trim();
  return value ? value : undefined;
}

function parseBool(raw: string | undefined, fallback: boolean): boolean {
  switch (raw?.trim()) {
    case "1":
    case "true":
    case "TRUE":
    case "yes":
    case "YES":
      return true;
    case "0":
    case "false":
    case "FALSE":
    case "no":
    case "NO":
      return false;
    default:
      return fallback;
  }
}

function parseIntValue(raw: string | undefined, fallback: number): number {
  const parsed = Number.parseInt(raw?.trim() ?? "", 10);
  return Number.isNaN(parsed) ? fallback : parsed;
}

function parseFloatValue(raw: string | undefined, fallback: number): number {
  const parsed = Number.parseFloat(raw?.trim() ?? "");
  return Number.isNaN(parsed) ? fallback : parsed;
}

function parseOptionalNumber(raw: string | undefined, asInt: boolean): number | undefined {
  const value = raw?.trim();
  if (!value) {
    return undefined;
  }
  const parsed = asInt ? Number.parseInt(value, 10) : Number.parseFloat(value);
  return Number.isNaN(parsed) ? undefined : parsed;
}

function nonempty(raw: string | undefined): string | undefined {
  const value = raw?.trim();
  return value ? value : undefined;
}

export function requireEnv(
  name: string,
  expectedType: string,
  examples: readonly string[],
  value: string | undefined,
): string {
  const trimmed = nonempty(value);
  if (trimmed) {
    return trimmed;
  }
  throw new MissingEnvError({ name, expectedType, examples });
}

function pick(
  keys: readonly string[],
  order: readonly string[],
  shell: Record<string, string | undefined>,
  dotenv: Record<string, string | undefined>,
  flags: Record<string, string | undefined>,
  fallback: string | undefined,
): string | undefined {
  for (const source of order) {
    const map = source === "flags" ? flags : source === "env_file" ? dotenv : shell;
    for (const key of keys) {
      const value = nonempty(map[key]);
      if (value !== undefined) {
        return value;
      }
    }
  }
  return nonempty(fallback);
}

function unquote(value: string): string {
  const trimmed = value.trim();
  if (
    (trimmed.startsWith("\"") && trimmed.endsWith("\"")) ||
    (trimmed.startsWith("'") && trimmed.endsWith("'"))
  ) {
    return trimmed.slice(1, -1);
  }
  return trimmed;
}

export function parseDotenv(text: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const raw of text.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) {
      continue;
    }
    const body = line.startsWith("export ") ? line.slice("export ".length).trim() : line;
    const eq = body.indexOf("=");
    if (eq <= 0) {
      continue;
    }
    const key = body.slice(0, eq).trim();
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) {
      continue;
    }
    out[key] = unquote(body.slice(eq + 1));
  }
  return out;
}

function dotenvEnabled(): boolean {
  const value = typeof process !== "undefined" ? process.env.FLAGS2ENV_DOTENV : undefined;
  return !["0", "false", "FALSE", "no", "NO"].includes(value?.trim() ?? "");
}

export function loadDotenvFiles(files: readonly string[]): Record<string, string> {
  if (!dotenvEnabled() || typeof process === "undefined") {
    return {};
  }
  let fs: { readFileSync: (path: string, encoding: string) => string } | undefined;
  try {
    fs = require("fs") as { readFileSync: (path: string, encoding: string) => string };
  } catch {
    return {};
  }
  return files.reduce<Record<string, string>>((acc, path) => {
    try {
      return { ...acc, ...parseDotenv(fs!.readFileSync(path, "utf8")) };
    } catch {
      return acc;
    }
  }, {});
}
export interface MissingEnv {
  readonly name: string;
  readonly expectedType: string;
  readonly examples: readonly string[];
}

export class MissingEnvError extends Error implements MissingEnv {
  readonly name: string;
  readonly expectedType: string;
  readonly examples: readonly string[];
  constructor(fields: MissingEnv) {
    super(`missing required environment variable ${fields.name}\n  expected type: ${fields.expectedType}\n  examples: ${fields.examples.join(", ")}`);
    this.name = fields.name;
    this.expectedType = fields.expectedType;
    this.examples = fields.examples;
  }
}

/** Resolve env-key -> value. Empty values fall through to the next source. */
export function loadEnvMap(
  shell: Record<string, string | undefined>,
  dotenv: Record<string, string | undefined>,
  flags: Record<string, string | undefined> = {},
): Record<string, string> {
  const out: Record<string, string> = {};
  const allow_non_loopback = pick(["ORES_OTEL_SIDECAR_ALLOW_NON_LOOPBACK"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, "false");
  if (allow_non_loopback !== undefined) out["ORES_OTEL_SIDECAR_ALLOW_NON_LOOPBACK"] = allow_non_loopback;
  const bind = pick(["FIDUCIA_SIDECAR_BIND"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, "127.0.0.1:9090");
  if (bind !== undefined) out["FIDUCIA_SIDECAR_BIND"] = bind;
  const fiducia_az = pick(["FIDUCIA_AZ"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (fiducia_az !== undefined) out["FIDUCIA_AZ"] = fiducia_az;
  const fiducia_brain_url = pick(["FIDUCIA_BRAIN_URL"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (fiducia_brain_url !== undefined) out["FIDUCIA_BRAIN_URL"] = fiducia_brain_url;
  const fiducia_export_target = pick(["FIDUCIA_EXPORT_TARGET"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (fiducia_export_target !== undefined) out["FIDUCIA_EXPORT_TARGET"] = fiducia_export_target;
  const fiducia_internal_secret = pick(["FIDUCIA_INTERNAL_SECRET"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (fiducia_internal_secret !== undefined) out["FIDUCIA_INTERNAL_SECRET"] = fiducia_internal_secret;
  const fiducia_log_sink = pick(["FIDUCIA_LOG_SINK"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (fiducia_log_sink !== undefined) out["FIDUCIA_LOG_SINK"] = fiducia_log_sink;
  const fiducia_log_source = pick(["FIDUCIA_LOG_SOURCE"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (fiducia_log_source !== undefined) out["FIDUCIA_LOG_SOURCE"] = fiducia_log_source;
  const fiducia_node_address = pick(["FIDUCIA_NODE_ADDRESS"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (fiducia_node_address !== undefined) out["FIDUCIA_NODE_ADDRESS"] = fiducia_node_address;
  const fiducia_node_id = pick(["FIDUCIA_NODE_ID"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (fiducia_node_id !== undefined) out["FIDUCIA_NODE_ID"] = fiducia_node_id;
  const fiducia_node_log_source = pick(["FIDUCIA_NODE_LOG_SOURCE"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (fiducia_node_log_source !== undefined) out["FIDUCIA_NODE_LOG_SOURCE"] = fiducia_node_log_source;
  const fiducia_node_url = pick(["FIDUCIA_NODE_URL"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (fiducia_node_url !== undefined) out["FIDUCIA_NODE_URL"] = fiducia_node_url;
  const fiducia_node_version = pick(["FIDUCIA_NODE_VERSION"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (fiducia_node_version !== undefined) out["FIDUCIA_NODE_VERSION"] = fiducia_node_version;
  const fiducia_rack = pick(["FIDUCIA_RACK"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (fiducia_rack !== undefined) out["FIDUCIA_RACK"] = fiducia_rack;
  const fiducia_region = pick(["FIDUCIA_REGION"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (fiducia_region !== undefined) out["FIDUCIA_REGION"] = fiducia_region;
  const fiducia_sidecar_role = pick(["FIDUCIA_SIDECAR_ROLE"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (fiducia_sidecar_role !== undefined) out["FIDUCIA_SIDECAR_ROLE"] = fiducia_sidecar_role;
  const port = pick(["PORT"], ["flags", "env_shell", "env_file"], shell, dotenv, flags, undefined);
  if (port !== undefined) out["PORT"] = port;
  return out;
}

const DOTENV_FILES: readonly string[] = [".env"];
/** Effectful overlay: `.env` files then `process.env`, ranked per key. */
export function loadEnvMapFromOs(
  shell: Record<string, string | undefined> = typeof process !== "undefined" ? process.env : {},
): Record<string, string> {
  return loadEnvMap(shell, loadDotenvFiles(DOTENV_FILES), {});
}
